const tanks = [
  { name: "A", fuel: 42 },
  { name: "B", fuel: 27 },
  { name: "C", fuel: 36 },
];

// total ve average'ı hesapla
const total = tanks.reduce((sum, t) => sum + t.fuel, 0);
