assert(average === 35, "average 35 olmalı.");
assert(!/\b105\b/.test(_code) && !/\b35\b/.test(_code), "Sonuçları elle yazma; reduce ve length ile hesapla.");
assert(/\.reduce\s*\(/.test(_code), "Toplamı reduce ile bul.");

challenge.starter:
const scores = [40, 100, 9, 25, 7];

// sorted, top3, allPassed, hasPerfect

console.log(sorted, top3, allPassed, hasPerfect);

challenge.solution:
const scores = [40, 100, 9, 25, 7];

// sorted, top3, allPassed, hasPerfect
const sorted = scores.slice().sort((a, b) => a - b);
const top3 = scores.slice().sort((a, b) => b - a).slice(0, 3);
const allPassed = scores.every((s) => s > 5);
const hasPerfect = scores.some((s) => s === 100);

console.log(sorted, top3, allPassed, hasPerfect);

check.js:
assert(same(sorted, [7, 9, 25, 40, 100]), "sorted [7, 9, 25, 40, 100] olmalı. Sayıları sıralarken (a, b) => a - b kullan.");
assert(same(top3, [100, 40, 25]), "top3 [100, 40, 25] olmalı.");
assert(same(scores, [40, 100, 9, 25, 7]), "scores dizisi değişmemeli; sıralamadan önce slice() ile kopyala.");
assert(allPassed === true && hasPerfect === true, "allPassed ve hasPerfect true olmalı.");
assert(/\.every\s*\(/.test(_code) && /\.some\s*\(/.test(_code), "every ve some kullanmalısın.");

