project_task.solution:
const players = [
  { name: "Ada", score: 120 },
  { name: "Can", score: 85 },
  { name: "Ece", score: 150 },
  { name: "Mert", score: 95 },
];

function leaderboard(list) {
  // kopyala, sırala, sonra map ile metne çevir
  return list
    .slice()
    .sort((a, b) => b.score - a.score)
    .map((p, i) => `${i + 1}. ${p.name} - ${p.score}`);
}

console.log(leaderboard(players));

check.js:
const board = leaderboard(players);
assert(Array.isArray(board), "leaderboard bir dizi döndürmeli.");
assert(same(board, ["1. Ece - 150", "2. Ada - 120", "3. Mert - 95", "4. Can - 85"]), "Sonuç ['1. Ece - 150', '2. Ada - 120', '3. Mert - 95', '4. Can - 85'] olmalı.");
assert(players[0].name === "Ada", "Asıl players dizisinin sırası değişmemeli; önce slice() ile kopyala.");
const other = leaderboard([{ name: "Zeynep", score: 5 }, { name: "Efe", score: 70 }]);
assert(same(other, ["1. Efe - 70", "2. Zeynep - 5"]), "Fonksiyon başka oyuncu listeleriyle de çalışmalı.");

