project_task.solution:
const tasks = [
  { title: "Matematik ödevi", minutes: 40, done: true },
  { title: "Fizik tekrarı", minutes: 30, done: false },
  { title: "İngilizce kelimeler", minutes: 15, done: true },
  { title: "Kitap okuma", minutes: 25, done: true },
];

function stats(list) {
  // tamamlananları süz, dakikalarını topla
  const finished = list.filter((t) => t.done);
  const minutes = finished.reduce((sum, t) => sum + t.minutes, 0);
  return { done: finished.length, minutes };
}

const s = stats(tasks);
console.log(`Tamamlanan: ${s.done} görev, ${s.minutes} dakika`);

check.js:
const r = stats(tasks);
assert(r && r.done === 3 && r.minutes === 80, "stats(tasks) { done: 3, minutes: 80 } döndürmeli.");
const r2 = stats([{ title: "X", minutes: 10, done: false }, { title: "Y", minutes: 50, done: true }]);
assert(r2.done === 1 && r2.minutes === 50, "Yalnızca tamamlanan görevlerin dakikaları toplanmalı; fonksiyon başka listelerle de çalışmalı.");
const r3 = stats([]);
assert(r3.done === 0 && r3.minutes === 0, "Boş listede { done: 0, minutes: 0 } olmalı (reduce'a başlangıç değeri ver).");
assert(_lines.includes("Tamamlanan: 3 görev, 80 dakika"), "Çıktıda 'Tamamlanan: 3 görev, 80 dakika' görünmeli.");

