project_task.solution:
const answers = [
  { question: "Ay hangi gezegenin uydusu?", correct: true, points: 10 },
  { question: "En büyük gezegen hangisi?", correct: false, points: 10 },
  { question: "Kızıl gezegen hangisi?", correct: true, points: 20 },
  { question: "Halkalı gezegen hangisi?", correct: false, points: 20 },
];

function summary(list) {
  // correctCount, score, missed
  const right = list.filter((a) => a.correct);
  return {
    correctCount: right.length,
    score: right.reduce((sum, a) => sum + a.points, 0),
    missed: list.filter((a) => !a.correct).map((a) => a.question),
  };
}

console.log(summary(answers));

check.js:
const r = summary(answers);
assert(r && r.correctCount === 2, "correctCount 2 olmalı.");
assert(r.score === 30, "score 30 olmalı (yalnızca doğru cevapların puanları).");
assert(same(r.missed, ["En büyük gezegen hangisi?", "Halkalı gezegen hangisi?"]), "missed yanlış cevaplanan soruların metinleri olmalı.");
const r2 = summary([{ question: "A?", correct: true, points: 5 }]);
assert(r2.correctCount === 1 && r2.score === 5 && same(r2.missed, []), "Fonksiyon başka cevap listeleriyle de çalışmalı.");
